        assertEquals(1,move.hit(Match3Goals.Kind.EGG));assertEquals(0,move.directUnits);assertEquals("靠近鸡蛋",move.reason);
        assertTrue(move.result.unknowns.contains("chick_spawn_count_positions_unknown"));
