        assertEquals(1,best.directUnits);assertTrue(best.allTargetsFinish);assertEquals("消除灰毛球",best.reason);
        assertEquals('B',best.result.after.cell(0,1).color);assertEquals(1,best.result.after.cell(0,1).iceLayers);
