    @Test public void aLineIsLegalWithoutFormingATripleAndHitsOnlyItsObservedAxis() {
        Match3Position p=replace(board("RBG","GBR","YPG"),1,1,Match3Position.Cell.animal('B').withEffect(Match3Position.Effect.HORIZONTAL));
        Match3RuleEngine.Result row=settle(p,Match3Action.Type.ACTIVATE,4,4);
        assertEquals(Match3Position.Kind.VACANT,row.after.cell(1,0).kind);assertEquals(Match3Position.Kind.ANIMAL,row.after.cell(0,1).kind);
        assertEquals(3,row.events.stream().filter(e->e.type==Match3RuleEngine.EventType.CLEAR).count());
        assertNotNull(action(p,Match3Action.Type.LINE_SWAP,4,5));
        p=replace(p,1,1,Match3Position.Cell.animal('B').withEffect(Match3Position.Effect.VERTICAL));
        Match3RuleEngine.Result col=settle(p,Match3Action.Type.ACTIVATE,4,4);
        assertEquals(Match3Position.Kind.ANIMAL,col.after.cell(1,0).kind);assertEquals(Match3Position.Kind.VACANT,col.after.cell(0,1).kind);
    }
    @Test public void lineSwapActivatesAtTheDestinationWithTheCorrectDirection() {
        Match3Position p=replace(board("RBG","GBR","YPG"),1,1,Match3Position.Cell.animal('B').withEffect(Match3Position.Effect.VERTICAL));
        Match3RuleEngine.Result r=settle(p,Match3Action.Type.LINE_SWAP,4,5);
        assertEquals(Match3Position.Kind.VACANT,r.after.cell(0,2).kind);assertEquals(Match3Position.Kind.VACANT,r.after.cell(2,2).kind);
        assertEquals('R',r.after.cell(1,1).color);
    }
