        Match3Position p=replace(board("RRR","GRB"),0,0,Match3Position.Cell.animal('R').withEffect(Match3Position.Effect.HORIZONTAL));
        p=replace(p,0,1,Match3Position.Cell.animal('R').withEffect(Match3Position.Effect.VERTICAL));
