    @Test public void chargedPairRequiresBothObservedFullEnergyStates() {
        Match3Position p=replace(replace(board("RBG","GBR"),0,0,Match3Position.Cell.observed(Match3Position.Kind.DYE_BABY,"dye_baby",0,-1)
                .withEnergy(5,5)),0,1,Match3Position.Cell.observed(Match3Position.Kind.STAR_BOTTLE,"star_bottle",0,-1).withEnergy(4,5));
        for(Match3Action a:Match3Action.enumerate(p))assertNotEquals(Match3Action.Type.CHARGED_PAIR,a.type);
        p=replace(p,0,1,p.cell(0,1).withEnergy(5,5));
        Match3RuleEngine.Result r=settle(p,Match3Action.Type.CHARGED_PAIR,0,1);
        assertEquals(1,r.collected(Match3Goals.Kind.RED,Match3Goals.Mode.CLEAR));assertFalse(r.successorKnown);
    }
    @Test public void fourFiveAndTShapesGenerateDifferentSpecialsWithoutInventingAnchors() {
        for(String[] rows:new String[][]{{"RGRR","HRHH"},{"RGRRR","HRHHH"},{"HRH","RGR","HRH","HRH"}}) {
            Match3Position p=board(rows);Match3RuleEngine.Result r=settle(p,Match3Action.Type.SWAP,
                    1,rows.length==4?4:rows[0].length()+1);
            String expected=rows.length==4?"blast":rows[0].length()==4?"line_horizontal":"magic_bird";
            assertEquals(1,r.potentialSpecials);assertTrue(r.events.stream().anyMatch(e->e.type==Match3RuleEngine.EventType.GENERATE && e.ruleId.equals(expected)));
            assertFalse(r.successorKnown);assertTrue(r.unknowns.contains("generation_anchor_unobserved"));
        }
    }
    @Test public void specialFurballDamageIsPermanentAndInvincibleDamageIsTemporary() {
        Match3Position p=replace(replace(board("RGB"),0,0,Match3Position.Cell.animal('R').withEffect(Match3Position.Effect.HORIZONTAL)),
                0,1,Match3Position.Cell.observed(Match3Position.Kind.FURBALL,"furball",1,-1));
        Match3RuleEngine.Result r=settle(p,Match3Action.Type.ACTIVATE,0,0);
        assertEquals(1,r.collected(Match3Goals.Kind.FURBALL,Match3Goals.Mode.CLEAR));assertEquals(Match3Position.Kind.VACANT,r.after.cell(0,1).kind);
        p=replace(p,0,1,Match3Position.Cell.observed(Match3Position.Kind.INVINCIBLE_FURBALL,"invincible_furball",1,-1));
        r=settle(p,Match3Action.Type.ACTIVATE,0,0);assertEquals(0,r.collected(Match3Goals.Kind.FURBALL,Match3Goals.Mode.CLEAR));
        assertEquals(-1,r.after.cell(0,1).absentTurns);assertEquals(Match3Position.Kind.INVINCIBLE_FURBALL,r.after.cell(0,1).kind);
    }
