    @Test public void poisonPriorityDependsOnTheObservedTaskAndNonFullBottle() {
        Match3Position p=replace(board("HHHHHHH","BGBHRGR","HBHHHRH"),0,1,Match3Position.Cell.observed(Match3Position.Kind.POISON,"poison",1,-1));
        p=replace(p,0,6,Match3Position.Cell.observed(Match3Position.Kind.STAR_BOTTLE,"star_bottle",0,-1).withEnergy(2,5));
        Match3MoveValue red=Match3MoveRanker.rankedMoves(p,goals(Match3Goals.Kind.RED,3,Match3Goals.Mode.CLEAR,2)).get(0);
        assertEquals(5,red.swap.fromCol);assertTrue(red.allTargetsFinish);
        Match3MoveValue charge=Match3MoveRanker.rankedMoves(p,goals(Match3Goals.Kind.STAR_BOTTLE,3,Match3Goals.Mode.CHARGE,2)).get(0);
        assertEquals(1,charge.swap.fromCol);assertEquals(0,charge.directUnits);assertEquals("准备充能星星瓶",charge.reason);
        p=replace(p,0,6,p.cell(0,6).withEnergy(5,5));
        Match3RuleEngine.Result r=settle(p,Match3Action.Type.SWAP,8,15);
        assertEquals(0,r.preparation(Match3Goals.Kind.STAR_BOTTLE,Match3Goals.Mode.CHARGE));
    }
