    @Test public void knownTwoStepUnlockFindsTheFollowUpButTheFinalStepDoesNotBorrowIt() {
        Match3Position p=replace(board("HHHH","HHHH","RGRH","HRHH","BYBH","HBHH"),3,1,
                Match3Position.Cell.animal('R').withCover(Match3Position.Cover.LOCK,1));
        int[] next=new int[24];Arrays.fill(next,-1);
        p=new Match3Position(p.copyCells(),new Match3Topology(next,new Match3Position.Kind[24],false,"fixture_no_gravity_or_refill"));
        Match3Goals goals=goals(Match3Goals.Kind.RED,3,Match3Goals.Mode.CLEAR,2);
        Match3MoveValue first=Match3MoveValue.evaluate(p,goals,action(p,Match3Action.Type.SWAP,17,21).geometry);
        assertEquals(0,first.directUnits);assertTrue(first.result.successorKnown);
        Match3MoveValue searched=Match3Search.apply(Collections.singletonList(first),goals,Collections.emptySet(),()->0L).get(0);
        assertEquals(2,searched.search.depth);assertEquals(3,searched.search.units);assertTrue(searched.search.finish);
        Match3Goals finalStep=goals(Match3Goals.Kind.RED,3,Match3Goals.Mode.CLEAR,1);
        assertEquals(1,Match3Search.apply(Collections.singletonList(first),finalStep,Collections.emptySet(),()->0L).get(0).search.depth);
        java.util.concurrent.atomic.AtomicLong time=new java.util.concurrent.atomic.AtomicLong();
        Match3MoveValue exhausted=Match3Search.apply(Collections.singletonList(first),goals,Collections.emptySet(),
                ()->time.getAndAdd(Match3Search.MAX_NANOS)).get(0);
        assertEquals("budget_fallback",exhausted.search.stopped);assertEquals(1,exhausted.search.depth);assertEquals(0,exhausted.search.units);
    }
